table('Danh mục thuật ngữ và từ viết tắt',['Từ viết tắt','Diễn giải'],[['DSS','Decision Support System – Hệ thống hỗ trợ ra quyết định'],['MBA','Market Basket Analysis – Phân tích giỏ hàng'],['CSV','Comma Separated Values – Tệp dữ liệu phân tách bằng dấu phẩy'],['DBMS','Database Management System – Hệ quản trị cơ sở dữ liệu'],['ERD','Entity Relationship Diagram – Sơ đồ thực thể liên kết'],['MVC','Model View Controller – Mô hình tổ chức ứng dụng'],['API','Application Programming Interface – Giao diện lập trình ứng dụng'],['SQL','Structured Query Language – Ngôn ngữ truy vấn có cấu trúc'],['FP','Frequent Pattern – Mẫu phổ biến'],['UI','User Interface – Giao diện người dùng']])
